<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Agende seu horário | Clínica Vida Plena</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="assets/portal.css"><link rel="stylesheet" href="assets/figma-theme.css"></head><body class="booking-page"><header class="booking-header"><a class="brand" href="?page=commercial"><span class="brand-mark">n</span><span>NOA<span class="brand-light">CONNECT</span></span></a><span>AGENDAMENTO ONLINE</span></header><main class="booking-shell"><div class="booking-brand"><span class="clinic-avatar big">V</span><div><p class="eyebrow">CLÍNICA VIDA PLENA</p><h1>Agende seu horário</h1><p>Escolha um serviço e encontre um horário para você.</p></div></div><div class="booking-progress"><span class="booking-step active"><i>1</i> Serviço</span><b></b><span class="booking-step"><i>2</i> Horário</span><b></b><span class="booking-step"><i>3</i> Seus dados</span></div><section class="booking-card" id="bookingStep1"><p class="eyebrow">ETAPA 1 DE 3</p><h2>O que você precisa?</h2><div class="service-options"><button class="service-choice selected" data-service="Consulta inicial"><span class="service-choice-icon">✳</span><span><b>Consulta inicial</b><small>Primeira avaliação · 50 min</small></span><strong>R$ 180</strong></button><button class="service-choice" data-service="Retorno"><span class="service-choice-icon">↻</span><span><b>Retorno</b><small>Acompanhamento · 30 min</small></span><strong>R$ 120</strong></button><button class="service-choice" data-service="Avaliação"><span class="service-choice-icon">◷</span><span><b>Avaliação especializada</b><small>Consulta completa · 60 min</small></span><strong>R$ 220</strong></button></div><label class="booking-label">Profissional<select id="bookingProfessional"><option>Dra. Ana Ribeiro · Clínica geral</option><option>Dr. Pedro Lima · Cardiologia</option><option>Dra. Júlia Nunes · Dermatologia</option></select></label><button class="primary-button booking-next" data-booking-next="2">Ver horários disponíveis <span>→</span></button></section>
<section class="booking-card hidden" id="bookingStep2"><p class="eyebrow">ETAPA 2 DE 3</p><h2>Escolha uma data e horário</h2><label class="booking-label">Data<input type="date" id="bookingDate" value="<?= e(date('Y-m-d', strtotime('+5 days'))) ?>"></label><p class="slot-heading" id="slotHeading">HORÁRIOS DISPONÍVEIS</p><div class="slot-grid"><?php foreach (['09:00','09:30','10:30','11:00','13:30','14:00','15:30','16:00'] as $slot): ?><button class="time-slot"><?= e($slot) ?></button><?php endforeach; ?></div><div class="booking-navigation"><button class="secondary-button" data-booking-next="1">← Voltar</button><button class="primary-button" data-booking-next="3" id="slotContinue" disabled>Continuar <span>→</span></button></div></section>
